identify.web_sdk:
// emailId: raw value for the hard identifier "email_id"
brweb.identify({
  email_id: String(emailId).trim().toLowerCase(),
});

// Standalone server-side identification when the checkout page loads: binds cart_id
// Send these as customer_ids with the Tracking API (POST /track/v2/projects/{project_token}/customers); there is no SDK identify call.
// customer_ids: { cart_id: cartId }

// Standalone identify call when the SMS consent form is submitted: binds phone_id, cookie
// The cookie is bound by the SDK automatically.
brweb.identify({
  phone_id: phoneId,
});

// Standalone identify call when the user logs out: binds registered, cookie
// The cookie is bound by the SDK automatically.
brweb.identify({
  registered: registered,
});

