identify.tracking_api:
// Sending a hard id together with the cookie in customer_ids merges the cookie profile into the customer.
// Tracking API: POST /track/v2/projects/{project_token}/customers (see https://documentation.bloomreach.com/data-hub/reference/tracking-api-overview)
{
  "customer_ids": {
    "cookie": "<cookie>",
    "email_id": "<email_id>"
  },
  "properties": {}
}

// Standalone server-side identification when the checkout page loads: binds cart_id
// Tracking API: POST /track/v2/projects/{project_token}/customers (see https://documentation.bloomreach.com/data-hub/reference/tracking-api-overview)
{
  "customer_ids": {
    "cart_id": "<cart_id>"
  },
  "properties": {}
}

// Standalone identify call (client-side in production; the Tracking API equivalent is shown) when first page view of a new visitor: binds cookie
// Tracking API: POST /track/v2/projects/{project_token}/customers (see https://documentation.bloomreach.com/data-hub/reference/tracking-api-overview)
{
  "customer_ids": {
    "cookie": "<cookie>"
  },
  "properties": {}
}

// Standalone identify call (client-side in production; the Tracking API equivalent is shown) when the SMS consent form is submitted: binds phone_id, cookie
// Tracking API: POST /track/v2/projects/{project_token}/customers (see https://documentation.bloomreach.com/data-hub/reference/tracking-api-overview)
{
  "customer_ids": {
    "phone_id": "<phone_id>",
    "cookie": "<cookie>"
  },
  "properties": {}
}

// Standalone identify call (client-side in production; the Tracking API equivalent is shown) when the user logs out: binds registered, cookie
// Tracking API: POST /track/v2/projects/{project_token}/customers (see https://documentation.bloomreach.com/data-hub/reference/tracking-api-overview)
{
  "customer_ids": {
    "registered": "<registered>",
    "cookie": "<cookie>"
  },
  "properties": {}
}

identify.gtm_datalayer:
// emailId: raw value for the hard identifier "email_id"
