update.tracking_api:
// Customer attributes are updated with the same customers call; the customer is addressed by its hard id.
// Tracking API: POST /track/v2/projects/{project_token}/customers (see https://documentation.bloomreach.com/data-hub/reference/tracking-api-overview)
{
  "customer_ids": {
    "email_id": "<email_id>",
    "phone_id": "<phone_id>",
    "registered": "<registered>"
  },
  "properties": {
    "email": "<email>",
    "first_name": "<firstName>",
    "last_name": "<lastName>",
    "phone": "<phone>"
  }
}

